SELECT CASE WHEN s.rating >= 3.7 THEN 'high' WHEN s.rating >= 1.4 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(*) AS row_count, COUNT(CASE WHEN p.category = 'Home' THEN 1 END) AS home_count FROM products p LEFT JOIN suppliers s ON p.supplier_id = s.id WHERE p.launch_date < '2025-07-01' GROUP BY CASE WHEN s.rating >= 3.7 THEN 'high' WHEN s.rating >= 1.4 THEN 'mid' ELSE 'low' END
